{"action":"write","path":"sections/05-impact.html","content":"<section id="impact">
  <h2>Our Impact</h2>
  <p>Every cup supports community. Here’s what we’ve achieved this year.</p>
  <div class="stats">
    <div class="stat">
      <span class="num">2,500</span>
      <span class="label">community meals served</span>
    </div>
    <div class="stat">
      <span class="num">120</span>
      <span class="label">training hours delivered</span>
    </div>
    <div class="stat">
      <span class="num">35</span>
      <span class="label">graduates placed in jobs</span>
    </div>
  </div>
  <style>
    #impact {font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif; color:#1e2a1e; background:#fff8f0; padding:64px 24px;}
    #impact h2 {font-size:36px; line-height:1.2; margin:0 0 12px; color:#1e2a1e;}
    #impact > p {margin:0 0 32px; font-size:18px; color:#3a4a3a; max-width:720px;}
    #impact .stats {display:flex; flex-wrap:wrap; gap:24px; justify-content:space-between;}
    #impact .stat {flex:1 1 220px; background:#fff; border:1px solid #e6d9c8; border-radius:16px; padding:24px; text-align:center; box-shadow:0 2px 8px rgba(30,42,30,.06);}
    #impact .num {display:block; font-size:48px; font-weight:700; color:#1e2a1e; line-height:1; margin-bottom:8px;}
    #impact .label {display:block; font-size:16px; color:#4a5a4a; text-transform:uppercase; letter-spacing:.4px;}
    @media (max-width:600px){
      #impact h2 {font-size:28px;}
      #impact .num {font-size:40px;}
      #impact .stats {gap:16px;}
      #impact .stat {padding:20px;}
    }
  </style>
</section>
"}
